from collections.abc import Generator
from dataclasses import dataclass
from enum import Enum, auto

from tiktoken import Encoding

from pdf_craft.transformer.xml_translator.segment import InlineSegment, TextSegment
from .common import DATA_ORIGIN_LEN_KEY

_ID_WEIGHT = 80
_ELLIPSIS = "..."


@dataclass
class ScoreSegment:
    text_segment: TextSegment
    left_parents: list[InlineSegment]
    right_parents: list[InlineSegment]
    text_tokens: list[int]
    score: int


def expand_to_score_segments(encoding: Encoding, inline_segment: InlineSegment) -> Generator[ScoreSegment, None, None]:
    for i, score_segment in enumerate(_do_expand_inline_segment(inline_segment)):
        xml_text = "".join(
            _render_score_segment(
                score_segment=score_segment,
                is_first=(i == 0),
            )
        )
        score_segment.text_tokens = encoding.encode(score_segment.text_segment.text)
        score_segment.score = len(encoding.encode(xml_text)) + sum(
            _ID_WEIGHT for parent in score_segment.left_parents if parent.id is not None
        )
        yield score_segment


def truncate_score_segment(
    encoding: Encoding,
    score_segment: ScoreSegment,
    remain_head: bool,
    remain_score: int,
):
    fixed_score = score_segment.score - len(score_segment.text_tokens)
    if remain_score <= fixed_score:
        # 裁剪仅能减少 text 部分的 tokens 数。
        # 而 XML 本身头尾占用的 tokens 数，以及 ID 占用加权分属于 fixed_score 部分，无法裁剪
        # 当发现将文字删光后才能达标时，不如直接放弃整段内容
        return None

    remain_text_tokens_count = remain_score - fixed_score

    # remain_text_tokens_count cannot be 0 here
    if remain_head:
        remain_text = encoding.decode(score_segment.text_tokens[:remain_text_tokens_count])
    else:
        remain_text = encoding.decode(score_segment.text_tokens[-remain_text_tokens_count:])

    if not remain_text.strip():
        return None

    if remain_head:
        remain_text = f"{remain_text} {_ELLIPSIS}"
    else:
        remain_text = f"{_ELLIPSIS} {remain_text}"

    text_segment = score_segment.text_segment.clone()
    text_segment.text = remain_text

    return ScoreSegment(
        text_segment=text_segment,
        left_parents=score_segment.left_parents,
        right_parents=score_segment.right_parents,
        text_tokens=encoding.encode(remain_text),
        score=remain_text_tokens_count + fixed_score,
    )


def _render_score_segment(score_segment: ScoreSegment, is_first: bool):
    for i, parent in enumerate(score_segment.left_parents):
        yield "<"
        yield parent.parent.tag
        if parent.id is not None:
            yield ' id="99"'
        if is_first and i == 0:
            yield " "
            yield DATA_ORIGIN_LEN_KEY
            yield '="9999"'
        yield ">"

    yield score_segment.text_segment.text

    for parent in reversed(score_segment.right_parents):
        yield "</"
        yield parent.parent.tag
        yield ">"


def _do_expand_inline_segment(inline_segment: InlineSegment):
    text_segment: TextSegment | None = None
    left_parents: list[InlineSegment] = []
    right_parents: list[InlineSegment] = []

    for item in _expand_as_wrapped(inline_segment):
        if isinstance(item, TextSegment):
            if text_segment is None:
                text_segment = item
            else:
                yield ScoreSegment(
                    text_segment=text_segment,
                    left_parents=left_parents,
                    right_parents=right_parents,
                    text_tokens=[],
                    score=0,
                )
                text_segment = item
                left_parents = []
                right_parents = []

        elif isinstance(item, tuple):
            child_inline_segment, orientation = item
            if orientation == _Orientation.UP:
                if text_segment is not None:
                    yield ScoreSegment(
                        text_segment=text_segment,
                        left_parents=left_parents,
                        right_parents=right_parents,
                        text_tokens=[],
                        score=0,
                    )
                    text_segment = None
                    left_parents = []
                    right_parents = []
                left_parents.append(child_inline_segment)

            elif orientation == _Orientation.DOWN:
                if text_segment is None:
                    left_parents.clear()
                else:
                    right_parents.append(child_inline_segment)

    if text_segment is not None:
        yield ScoreSegment(
            text_segment=text_segment,
            left_parents=left_parents,
            right_parents=right_parents,
            text_tokens=[],
            score=0,
        )


class _Orientation(Enum):
    DOWN = auto()
    UP = auto()


def _expand_as_wrapped(inline_segment: InlineSegment):
    yield (inline_segment, _Orientation.UP)
    for child in inline_segment.children:
        if isinstance(child, InlineSegment):
            yield from _expand_as_wrapped(child)
        elif isinstance(child, TextSegment):
            yield child
    yield (inline_segment, _Orientation.DOWN)

from collections.abc import Generator
from dataclasses import dataclass
from xml.etree.ElementTree import Element

from tiktoken import Encoding

from pdf_craft.transformer.xml_translator.segment import BlockSegment, BlockSubmitter, TextSegment, search_text_segments
from pdf_craft.transformer.xml_translator.xml import plain_text
from .common import DATA_ORIGIN_LEN_KEY
from .stream_mapper import InlineSegmentMapping
from .validation import LEVEL_DEPTH, generate_error_message, nest_as_errors_group, truncate_errors_group


@dataclass
class _BlockStatus:
    weight: int
    submitter: BlockSubmitter


# 以爬山算法，将 LLM 中提交的内容中挑选出完成度更高的部分。
# 它通过拒绝每个子部分的相对低完成度提交，锁定每个子部分只能往更高完成度的方向移动
class HillClimbing:
    def __init__(
        self,
        encoding: Encoding,
        max_fill_displaying_errors: int,
        block_segment: BlockSegment,
    ) -> None:
        self._encoding: Encoding = encoding
        self._max_fill_displaying_errors: int = max_fill_displaying_errors
        self._block_statuses: dict[int, _BlockStatus] = {}
        self._block_segment: BlockSegment = block_segment

    def request_element(self) -> Element:
        element = self._block_segment.create_element()
        for child_element in element:
            text = plain_text(child_element)
            tokens = self._encoding.encode(text)
            child_element.set(DATA_ORIGIN_LEN_KEY, str(len(tokens)))
        return element

    def gen_mappings(self) -> Generator[InlineSegmentMapping | None, None, None]:
        for inline_segment in self._block_segment:
            id = inline_segment.id
            assert id is not None
            status = self._block_statuses.get(id, None)
            text_segments: list[TextSegment] | None = None
            if status is None:
                yield None
            else:
                submitted_element = status.submitter.submitted_element
                text_segments = list(search_text_segments(submitted_element))
                yield inline_segment.parent, text_segments

    def submit(self, element: Element) -> str | None:
        error_message, block_weights = self._validate_block_weights_and_error_message(element)

        for submitter in self._block_segment.submit(element):
            weight: int = 0  # 未出现在 block_weights 说明没有错误，已完成
            if block_weights:
                weight = block_weights.get(submitter.id, 0)
            status = self._block_statuses.get(submitter.id, None)
            if status is None:
                self._block_statuses[submitter.id] = _BlockStatus(
                    weight=weight,
                    submitter=submitter,
                )
            elif weight < status.weight:
                status.weight = weight
                status.submitter = submitter

        return error_message

    def _validate_block_weights_and_error_message(self, element: Element) -> tuple[str | None, dict[int, int] | None]:
        errors_group = nest_as_errors_group(
            errors=self._block_segment.validate(element),
        )
        if errors_group is None:
            return None, None

        block_weights: dict[int, int] = {}
        for block_group in errors_group.block_groups:
            block_id = block_group.block_id
            status = self._block_statuses.get(block_id, None)
            block_weights[block_id] = block_group.weight
            if status is not None and status.weight > block_group.weight:
                # 本轮完成度得到改善（weight 下降）应该排后，让出注意力给完成度尚未改善的部分
                for child_error in block_group.errors:
                    child_error.level -= LEVEL_DEPTH

        origin_errors_count = errors_group.errors_count
        errors_group = truncate_errors_group(
            errors_group=errors_group,
            max_errors=self._max_fill_displaying_errors,
        )
        if errors_group is None:
            return None, block_weights

        message = generate_error_message(
            encoding=self._encoding,
            errors_group=errors_group,
            omitted_count=origin_errors_count - errors_group.errors_count,
        )
        return message, block_weights

from collections.abc import Generator, Iterable
from dataclasses import dataclass
from typing import Generic, TypeVar, cast
from xml.etree.ElementTree import Element

from tiktoken import Encoding

from pdf_craft.transformer.xml_translator.segment import (
    BlockContentError,
    BlockError,
    BlockExpectedIDsError,
    BlockUnexpectedIDError,
    BlockWrongTagError,
    FoundInvalidIDError,
    InlineError,
    InlineExpectedIDsError,
    InlineLostIDError,
    InlineUnexpectedIDError,
    InlineWrongTagCountError,
)
from ..utils import ensure_list
from pdf_craft.transformer.xml_translator.xml import plain_text

_LEVEL_WEIGHT = 3
_MAX_TEXT_HINT_TOKENS_COUNT = 6


_BLOCK_EXPECTED_IDS_LEVEL = 6
_BLOCK_WRONG_TAG_LEVEL = 5
_BLOCK_FOUND_INVALID_ID_LEVEL = 4
_BLOCK_UNEXPECTED_ID_LEVEL = 3

_INLINE_EXPECTED_IDS_LEVEL = 3
_INLINE_LOST_ID_LEVEL = 2
_INLINE_FOUND_INVALID_ID_LEVEL = 1
_INLINE_WRONG_TAG_COUNT_LEVEL = 0
_INLINE_UNEXPECTED_ID_LEVEL = 0

ERROR = TypeVar("ERROR")
LEVEL_DEPTH = 7


@dataclass
class ErrorItem(Generic[ERROR]):
    error: ERROR
    index1: int
    index2: int
    level: int
    weight: int


@dataclass
class BlockErrorsGroup:
    block_id: int
    block_element: Element
    errors: list[ErrorItem[BlockError | FoundInvalidIDError] | ErrorItem[InlineError | FoundInvalidIDError]]

    @property
    def weight(self) -> int:
        return sum(e.weight for e in self.errors)


@dataclass
class ErrorsGroup:
    upper_errors: list[ErrorItem[BlockError | FoundInvalidIDError]]
    block_groups: list[BlockErrorsGroup]

    @property
    def errors_count(self) -> int:
        count = len(self.upper_errors)
        for block_group in self.block_groups:
            count += len(block_group.errors)
        return count


def nest_as_errors_group(errors: Iterable[BlockError | FoundInvalidIDError]) -> ErrorsGroup | None:
    return _create_errors_group(
        error_items=_transform_errors_to_items(errors),
    )


def truncate_errors_group(errors_group: ErrorsGroup, max_errors: int) -> ErrorsGroup | None:
    errors_items = list(_flatten_errors_group(errors_group))
    if len(errors_items) <= max_errors:
        return errors_group

    errors_items.sort(key=lambda item: (-item[1].level, item[1].index1, item[1].index2))
    errors_items = errors_items[:max_errors]

    return _create_errors_group(
        error_items=errors_items,
    )


def generate_error_message(encoding: Encoding, errors_group: ErrorsGroup, omitted_count: int = 0) -> None | str:
    message_lines: list[str] = []
    for upper_error in errors_group.upper_errors:
        message_lines.append(_format_block_error(upper_error.error))
    if message_lines:
        message_lines.append("")

    for i, block_group in enumerate(errors_group.block_groups):
        if i == 0:
            message_lines.append("")

        block_tag = block_group.block_element.tag
        error_count = len(block_group.errors)
        count_suffix = f" ({error_count} error{'s' if error_count != 1 else ''})"
        message_lines.append(f"In {block_tag}#{block_group.block_id}:{count_suffix}")

        for block_error in block_group.errors:
            message: str
            if isinstance(block_error.error, BlockError):
                message = _format_block_error(block_error.error)
            elif isinstance(block_error.error, InlineError):
                message = _format_inline_error(encoding, block_error.error, block_group.block_id)
            else:
                raise RuntimeError()
            message_lines.append(f"  - {message}")

    if not message_lines:
        return None

    header = (
        f"Found {errors_group.errors_count} error(s). Fix them and return "
        "the COMPLETE corrected XML (not just the changed parts):"
    )
    message_lines.insert(0, "")
    message_lines.insert(0, header)

    if omitted_count > 0:
        message_lines.append("")
        message_lines.append(
            f"... and {omitted_count} more error(s) omitted. "
            f"Fix the above errors first, then resubmit for remaining issues."
        )
        message_lines.append("")
        message_lines.append("Remember: Return the entire <xml>...</xml> block with all corrections applied.")
    else:
        message_lines.append("")
        message_lines.append("Return the entire <xml>...</xml> block with corrections.")

    return "\n".join(message_lines)


@dataclass
class _Block:
    id: int
    element: Element


def _transform_errors_to_items(errors: Iterable[BlockError | FoundInvalidIDError]):
    for i, block_error in enumerate(errors):
        if isinstance(block_error, BlockContentError):
            block = _Block(
                id=block_error.id,
                element=block_error.element,
            )
            for j, inline_error in enumerate(block_error.errors):
                level = _get_inline_error_level(inline_error)
                weight = _calculate_error_weight(inline_error, level)
                yield (
                    block,
                    ErrorItem(
                        error=inline_error,
                        index1=i,
                        index2=j,
                        level=level,
                        weight=weight,
                    ),
                )
        else:
            level = _get_block_error_level(block_error)
            weight = _calculate_error_weight(block_error, level)
            error_item: ErrorItem[BlockError | FoundInvalidIDError] = ErrorItem(
                error=block_error,
                index1=i,
                index2=0,
                level=level,
                weight=weight,
            )
            block: _Block | None = None
            if isinstance(block_error, BlockWrongTagError) and block_error.block is not None:
                block = _Block(
                    id=block_error.block[0],
                    element=block_error.block[1],
                )
            yield block, error_item


def _flatten_errors_group(
    errors_group: ErrorsGroup,
) -> Generator[
    tuple[
        _Block | None,
        ErrorItem[BlockError | FoundInvalidIDError] | ErrorItem[InlineError | FoundInvalidIDError],
    ],
    None,
    None,
]:
    for error in errors_group.upper_errors:
        yield None, error

    for block_group in errors_group.block_groups:
        block = _Block(
            id=block_group.block_id,
            element=block_group.block_element,
        )
        for error in block_group.errors:
            yield block, error


def _create_errors_group(
    error_items: Iterable[
        tuple[
            _Block | None,
            ErrorItem[BlockError | FoundInvalidIDError] | ErrorItem[InlineError | FoundInvalidIDError],
        ]
    ],
) -> ErrorsGroup | None:
    upper_errors: list[ErrorItem[BlockError | FoundInvalidIDError]] = []
    block_elements: dict[int, Element] = {}
    block_errors_dict: dict[
        int, list[ErrorItem[BlockError | FoundInvalidIDError] | ErrorItem[InlineError | FoundInvalidIDError]]
    ] = {}

    for block, error in error_items:
        if block is None:
            upper_errors.append(cast(ErrorItem[BlockError | FoundInvalidIDError], error))
        else:
            block_errors = ensure_list(block_errors_dict, block.id)
            block_errors.append(error)
            block_elements[block.id] = block.element

    if not upper_errors and not block_errors_dict:
        return None

    block_errors_groups: list[BlockErrorsGroup] = []
    for block_id, block_errors in block_errors_dict.items():
        block_element = block_elements.get(block_id)
        if block_element is None:
            continue

        block_error_group = BlockErrorsGroup(
            block_id=block_id,
            block_element=block_element,
            errors=sorted(block_errors, key=lambda e: (-e.weight, e.index1, e.index2)),
        )
        block_errors_groups.append(block_error_group)

    upper_errors.sort(key=lambda e: (-e.level, e.index1, e.index2))
    block_errors_groups.sort(key=lambda g: -g.weight)

    return ErrorsGroup(
        upper_errors=upper_errors,
        block_groups=block_errors_groups,
    )


def _calculate_error_weight(error: BlockError | InlineError | FoundInvalidIDError, level: int) -> int:
    # BlockExpectedIDsError 和 InlineExpectedIDsError 的权重乘以 id2element 数量
    if isinstance(error, (BlockExpectedIDsError, InlineExpectedIDsError)):
        return (_LEVEL_WEIGHT**level) * len(error.id2element)
    else:
        return _LEVEL_WEIGHT**level


def _get_block_error_level(error: BlockError | FoundInvalidIDError) -> int:
    if isinstance(error, BlockWrongTagError):
        return _BLOCK_WRONG_TAG_LEVEL
    elif isinstance(error, BlockExpectedIDsError):
        return _BLOCK_EXPECTED_IDS_LEVEL
    elif isinstance(error, BlockUnexpectedIDError):
        return _BLOCK_UNEXPECTED_ID_LEVEL
    elif isinstance(error, FoundInvalidIDError):
        return _BLOCK_FOUND_INVALID_ID_LEVEL
    else:
        return 0


def _get_inline_error_level(error: InlineError | FoundInvalidIDError) -> int:
    if isinstance(error, InlineLostIDError):
        return _INLINE_LOST_ID_LEVEL
    elif isinstance(error, InlineExpectedIDsError):
        return _INLINE_EXPECTED_IDS_LEVEL
    elif isinstance(error, InlineUnexpectedIDError):
        return _INLINE_UNEXPECTED_ID_LEVEL
    elif isinstance(error, InlineWrongTagCountError):
        return _INLINE_WRONG_TAG_COUNT_LEVEL
    elif isinstance(error, FoundInvalidIDError):
        return _INLINE_FOUND_INVALID_ID_LEVEL
    else:
        return 0


def _format_block_error(error: BlockError | FoundInvalidIDError) -> str:
    if isinstance(error, BlockWrongTagError):
        if error.block is None:
            return (
                f"Root tag mismatch: expected `<{error.expected_tag}>`, but found `<{error.instead_tag}>`. "
                f"Fix: Change the root tag to `<{error.expected_tag}>`."
            )
        else:
            return (
                f"Wrong tag for block at `{error.instead_tag}#{error.block[0]}`: "
                f'expected `<{error.expected_tag} id="{error.block[0]}">`, '
                f'but found `<{error.instead_tag} id="{error.block[0]}">`. '
                f"Fix: Change the tag to `<{error.expected_tag}>`."
            )
    elif isinstance(error, BlockExpectedIDsError):
        # Add context hints with original text content
        context_hints: list[str] = []
        for id, elem in sorted(error.id2element.items()):
            original_text = plain_text(elem).strip()
            if original_text:
                # Truncate to first 30 chars for block-level hints
                text_preview = original_text[:30] + "..." if len(original_text) > 30 else original_text
                context_hints.append(f'  - `<{elem.tag} id="{id}">`: "{text_preview}"')

        if context_hints:
            message = "Missing block elements (find translation and wrap):\n" + "\n".join(context_hints)
        else:
            # Fallback if no text hints available
            missing_elements = [f'<{elem.tag} id="{id}">' for id, elem in sorted(error.id2element.items())]
            elements_str = ", ".join(missing_elements)
            message = f"Missing expected blocks: {elements_str}. Fix: Add these missing blocks with the correct IDs."

        return message

    elif isinstance(error, BlockUnexpectedIDError):
        selector = f"{error.element.tag}#{error.id}"
        return f"Unexpected block found at `{selector}`. Fix: Remove this unexpected block."

    elif isinstance(error, FoundInvalidIDError):
        if error.invalid_id is None:
            example = f"<{error.element.tag}>"
        else:
            example = f'<{error.element.tag} id="{error.invalid_id}">'
        return f"Invalid or missing ID attribute: {example}. Fix: Ensure all blocks have valid numeric IDs."
    else:
        return "Unknown block error. Fix: Review the block structure."


def _format_inline_error(encoding: Encoding, error: InlineError | FoundInvalidIDError, block_id: int) -> str:
    if isinstance(error, InlineLostIDError):
        selector = _build_inline_selector(encoding, error.stack, block_id, element=error.element)
        return f"Element at `{selector}` is missing an ID attribute. Fix: Add the required ID attribute."

    elif isinstance(error, InlineExpectedIDsError):
        # Add context hints with original text content
        context_hints: list[str] = []
        for id, elem in sorted(error.id2element.items()):
            original_text = plain_text(elem).strip()
            if original_text:
                text_hint = _extract_text_hint(encoding, elem)
                context_hints.append(f'  - `<{elem.tag} id="{id}">`: "{text_hint}"')

        if context_hints:
            message = "Missing inline elements (find translation and wrap):\n" + "\n".join(context_hints)
        else:
            # Fallback if no text hints available
            missing_elements = [f'<{elem.tag} id="{id}">' for id, elem in sorted(error.id2element.items())]
            elements_str = ", ".join(missing_elements)
            message = f"Missing expected inline elements: {elements_str}. Fix: Add these missing inline elements."

        return message

    elif isinstance(error, InlineUnexpectedIDError):
        selector = f"{error.element.tag}#{error.id}"
        return f"Unexpected inline element at `{selector}`. Fix: Remove this unexpected element."

    elif isinstance(error, InlineWrongTagCountError):
        tag = error.found_elements[0].tag if error.found_elements else "unknown"
        selector = _build_inline_selector(encoding, error.stack, block_id, tag=tag)
        expected = error.expected_count
        found = len(error.found_elements)

        if expected == 0 and found > 0:
            # 情况1: 不应该有，但发现了
            return (
                f"Found unexpected `<{tag}>` elements at `{selector}`. "
                f"There should be none, but {found} were found. "
                f"Fix: Remove all `<{tag}>` elements from this location."
            )
        elif expected > 0 and found == 0:
            # 情况2: 应该有，但没找到
            return (
                f"Missing `<{tag}>` elements at `{selector}`. "
                f"Expected {expected}, but none were found. "
                f"Fix: Add {expected} `<{tag}>` element(s) to this location."
            )
        elif found > expected:
            # 情况3: 数量过多
            extra = found - expected
            return (
                f"Too many `<{tag}>` elements at `{selector}`. "
                f"Expected {expected}, but found {found} ({extra} extra). "
                f"Fix: Remove {extra} `<{tag}>` element(s)."
            )
        else:
            # 情况4: 数量过少
            missing = expected - found
            return (
                f"Too few `<{tag}>` elements at `{selector}`. "
                f"Expected {expected}, but only found {found} ({missing} missing). "
                f"Fix: Add {missing} more `<{tag}>` element(s)."
            )
    elif isinstance(error, FoundInvalidIDError):
        if error.invalid_id is None:
            example = f"<{error.element.tag}>"
        else:
            example = f'<{error.element.tag} id="{error.invalid_id}">'
        return f"Invalid inline ID: {example}. Fix: Ensure inline elements have valid numeric IDs."
    else:
        return "Unknown inline error. Fix: Review the inline structure."


def _build_inline_selector(
    encoding: Encoding,
    stack: list[Element],
    block_id: int,
    element: Element | None = None,
    tag: str | None = None,
) -> str:
    if element is not None:
        element_id = element.get("id")
        if element_id is not None:
            # 能用 ID 直接定位，就不必用路径定位
            return f"{element.tag}#{element_id}"
        tag = element.tag

    # 路径：block#id > parent > ... > tag
    block_tag = stack[0].tag if stack else "unknown"
    path_parts = [f"{block_tag}#{block_id}"]

    for parent in stack[1:]:
        path_parts.append(parent.tag)

    if tag:
        path_parts.append(tag)

    selector = " > ".join(path_parts)

    if element is not None:
        text_hint = _extract_text_hint(encoding, element)
        if text_hint:
            selector += f' (contains text: "{text_hint}")'
    return selector


def _extract_text_hint(encoding: Encoding, element: Element) -> str:
    text = plain_text(element).strip()
    if text:
        tokens = encoding.encode(text)
        if len(tokens) > _MAX_TEXT_HINT_TOKENS_COUNT:
            tokens = tokens[:_MAX_TEXT_HINT_TOKENS_COUNT]
            text = encoding.decode(tokens).strip() + " ..."
    return text

from collections.abc import Generator
from dataclasses import dataclass
from enum import Enum, auto
from xml.etree.ElementTree import Element

from pdf_craft.transformer.xml_translator.segment import TextSegment, combine_text_segments
from pdf_craft.transformer.xml_translator.xml import index_of_parent, is_inline_element, iter_with_stack
from .stream_mapper import InlineSegmentMapping


class SubmitKind(Enum):
    REPLACE = auto()
    APPEND_TEXT = auto()
    APPEND_BLOCK = auto()


def submit(element: Element, action: SubmitKind, mappings: list[InlineSegmentMapping]) -> Element:
    submitter = _Submitter(
        element=element,
        action=action,
        mappings=mappings,
    )
    replaced_root = submitter.do()
    if replaced_root is not None:
        return replaced_root

    return element


@dataclass
class _Node:
    raw_element: Element
    items: list[tuple[list[TextSegment], "_Node"]]  # empty for peak, non-empty for platform
    tail_text_segments: list[TextSegment]


class _Submitter:
    def __init__(
        self,
        element: Element,
        action: SubmitKind,
        mappings: list[InlineSegmentMapping],
    ) -> None:
        self._action: SubmitKind = action
        self._nodes: list[_Node] = list(_nest_nodes(mappings))
        self._parents: dict[int, Element] = self._collect_parents(element, mappings)

    def _collect_parents(self, element: Element, mappings: list[InlineSegmentMapping]):
        ids: set[int] = set(id(e) for e, _ in mappings)
        parents_dict: dict[int, Element] = {}
        for parents, child in iter_with_stack(element):
            if parents and id(child) in ids:
                parents_dict[id(child)] = parents[-1]
        return parents_dict

    def do(self):
        replaced_root: Element | None = None

        for node in self._nodes:
            submitted = self._submit_node(node)
            if replaced_root is None:
                replaced_root = submitted

        return replaced_root

    # @return replaced root element, or None if appended to parent
    def _submit_node(self, node: _Node) -> Element | None:
        if node.items or self._action == SubmitKind.APPEND_TEXT:
            return self._submit_by_text(node)
        else:
            return self._submit_by_block(node)

    def _submit_by_block(self, node: _Node) -> Element | None:
        parent = self._parents.get(id(node.raw_element), None)
        if parent is None:
            return node.raw_element

        preserved_elements: list[Element] = []
        if self._action == SubmitKind.REPLACE:
            for child in list(node.raw_element):
                if not is_inline_element(child):
                    child.tail = None
                    preserved_elements.append(child)

        index = index_of_parent(parent, node.raw_element)
        combined = self._combine_text_segments(node.tail_text_segments)

        if combined is not None:
            # 在 APPEND_BLOCK 模式下，如果是 inline tag，则在文本前面加空格
            if self._action == SubmitKind.APPEND_BLOCK and is_inline_element(combined) and combined.text:
                combined.text = " " + combined.text
            parent.insert(index + 1, combined)
            index += 1

        for elem in preserved_elements:
            parent.insert(index + 1, elem)
            index += 1

        if combined is not None or preserved_elements:
            if preserved_elements:
                preserved_elements[-1].tail = node.raw_element.tail
            elif combined is not None:
                combined.tail = node.raw_element.tail
            node.raw_element.tail = None

            if self._action == SubmitKind.REPLACE:
                parent.remove(node.raw_element)

        return None

    def _submit_by_text(self, node: _Node) -> Element | None:
        replaced_root: Element | None = None
        child_nodes = dict((id(node), node) for _, node in node.items)
        last_tail_element: Element | None = None
        tail_elements: dict[int, Element] = {}

        for child_element in node.raw_element:
            child_node = child_nodes.get(id(child_element), None)
            if child_node is not None:
                if last_tail_element is not None:
                    tail_elements[id(child_element)] = last_tail_element
                last_tail_element = child_element

        for text_segments, child_node in node.items:
            anchor_element = _find_anchor_in_parent(node.raw_element, child_node.raw_element)
            if anchor_element is None:
                # 防御性编程：理论上 anchor_element 不应该为 None，
                #           因为 _nest_nodes 已经通过 _check_includes 验证了包含关系。
                continue

            tail_element = tail_elements.get(id(anchor_element), None)
            items_preserved_elements: list[Element] = []

            if self._action == SubmitKind.REPLACE:
                end_index = index_of_parent(node.raw_element, anchor_element)
                items_preserved_elements = self._remove_elements_after_tail(
                    node_element=node.raw_element,
                    tail_element=tail_element,
                    end_index=end_index,
                )

            self._append_combined_after_tail(
                node_element=node.raw_element,
                text_segments=text_segments,
                tail_element=tail_element,
                anchor_element=anchor_element,
                append_to_end=False,
            )
            if items_preserved_elements:
                insert_position = index_of_parent(node.raw_element, anchor_element)
                for i, elem in enumerate(items_preserved_elements):
                    node.raw_element.insert(insert_position + i, elem)

        for _, child_node in node.items:
            submitted = self._submit_node(child_node)
            if replaced_root is None:
                replaced_root = submitted

        if node.raw_element:
            last_tail_element = node.raw_element[-1]
        else:
            last_tail_element = None

        tail_preserved_elements: list[Element] = []
        if self._action == SubmitKind.REPLACE:
            tail_preserved_elements = self._remove_elements_after_tail(
                node_element=node.raw_element,
                tail_element=last_tail_element,
                end_index=None,  # None 表示删除到末尾
            )
        self._append_combined_after_tail(
            node_element=node.raw_element,
            text_segments=node.tail_text_segments,
            tail_element=last_tail_element,
            anchor_element=None,
            append_to_end=True,
        )
        if tail_preserved_elements:
            for elem in tail_preserved_elements:
                node.raw_element.append(elem)

        return replaced_root

    def _remove_elements_after_tail(
        self,
        node_element: Element,
        tail_element: Element | None,
        end_index: int | None = None,
    ) -> list[Element]:
        if tail_element is None:
            start_index = 0
            node_element.text = None
        else:
            start_index = index_of_parent(node_element, tail_element) + 1
            tail_element.tail = None

        if end_index is None:
            end_index = len(node_element)

        preserved_elements: list[Element] = []
        for i in range(start_index, end_index):
            elem = node_element[i]
            if not is_inline_element(elem):
                elem.tail = None
                preserved_elements.append(elem)

        for i in range(end_index - 1, start_index - 1, -1):
            node_element.remove(node_element[i])

        return preserved_elements

    def _append_combined_after_tail(
        self,
        node_element: Element,
        text_segments: list[TextSegment],
        tail_element: Element | None,
        anchor_element: Element | None,
        append_to_end: bool,
    ) -> None:
        combined = self._combine_text_segments(text_segments)
        if combined is None:
            return

        if combined.text:
            will_inject_space = self._action == SubmitKind.APPEND_TEXT or (
                is_inline_element(combined) and self._action == SubmitKind.APPEND_BLOCK
            )
            if tail_element is not None:
                tail_element.tail = self._append_text_in_element(
                    origin_text=tail_element.tail,
                    append_text=combined.text,
                    will_inject_space=will_inject_space,
                )
            elif anchor_element is None:
                node_element.text = self._append_text_in_element(
                    origin_text=node_element.text,
                    append_text=combined.text,
                    will_inject_space=will_inject_space,
                )
            else:
                ref_index = index_of_parent(node_element, anchor_element)
                if ref_index > 0:
                    # 添加到前一个元素的 tail
                    prev_element = node_element[ref_index - 1]
                    prev_element.tail = self._append_text_in_element(
                        origin_text=prev_element.tail,
                        append_text=combined.text,
                        will_inject_space=will_inject_space,
                    )
                else:
                    # ref_element 是第一个元素，添加到 node_element.text
                    node_element.text = self._append_text_in_element(
                        origin_text=node_element.text,
                        append_text=combined.text,
                        will_inject_space=will_inject_space,
                    )

        if tail_element is not None:
            insert_position = index_of_parent(node_element, tail_element) + 1
        elif append_to_end:
            insert_position = len(node_element)
        elif anchor_element is not None:
            # 使用 ref_element 来定位插入位置
            # 如果文本被添加到前一个元素的 tail，则在前一个元素之后插入
            ref_index = index_of_parent(node_element, anchor_element)
            if ref_index > 0:
                # 在前一个元素之后插入
                insert_position = ref_index
            else:
                # ref_element 是第一个元素，插入到开头
                insert_position = 0
        else:
            insert_position = 0

        for i, child in enumerate(combined):
            node_element.insert(insert_position + i, child)

    def _combine_text_segments(self, text_segments: list[TextSegment]) -> Element | None:
        segments = (t.strip_block_parents() for t in text_segments)
        combined = next(combine_text_segments(segments), None)
        if combined is None:
            return None
        else:
            return combined[0]

    def _append_text_in_element(
        self,
        origin_text: str | None,
        append_text: str,
        will_inject_space: bool,
    ) -> str:
        if origin_text is None:
            return append_text
        elif will_inject_space:
            return origin_text.rstrip() + " " + append_text.lstrip()
        else:
            return origin_text + append_text


def _nest_nodes(mappings: list[InlineSegmentMapping]) -> Generator[_Node, None, None]:
    # 需要翻译的文字会被嵌套到两种不同的结构中。
    # 最常见的的是 peak 结构，例如如下结构，没有任何子结构（inline 标签不是视为子结构）。
    # 可直接文本替换或追加。
    # <div>Some text <b>bold text</b> more text.</div>
    #
    # 但是还有一种少见的 platform 结构，它内部被其他 peak/platform 切割。
    #   <div>
    #     Some text before.
    #     <!-- 如下 peak 将它的阅读流切段 -->
    #     <div>Paragraph 1.</div>
    #     Some text in between.
    #   </div>
    # 如果直接对它进行替换或追加，读者阅读流会被破坏，从而读起来怪异。
    # 正是因为这种结构的存在，必须还原成树型结构，然后用特殊的方式来处理 platform 结构。
    #
    # 总之，我们假设 95% 的阅读体验由 peak 提供，但为兼顾剩下的 platform 结构，故加此步骤。
    stack: list[_Node] = []

    for block_element, text_segments in mappings:
        keep_depth: int = 0
        upwards: bool = False
        for i in range(len(stack) - 1, -1, -1):
            if stack[i].raw_element is block_element:
                keep_depth = i + 1
                upwards = True
                break

        if not upwards:
            for i in range(len(stack) - 1, -1, -1):
                if _check_includes(stack[i].raw_element, block_element):
                    keep_depth = i + 1
                    break

        while len(stack) > keep_depth:
            child_node = _fold_top_of_stack(stack)
            if not upwards and child_node is not None:
                yield child_node

        if upwards:
            stack[keep_depth - 1].tail_text_segments.extend(text_segments)
        else:
            stack.append(
                _Node(
                    raw_element=block_element,
                    items=[],
                    tail_text_segments=list(text_segments),
                )
            )
    while stack:
        child_node = _fold_top_of_stack(stack)
        if child_node is not None:
            yield child_node


def _find_anchor_in_parent(parent: Element, descendant: Element) -> Element | None:
    for child in parent:
        if child is descendant:
            return descendant

    for child in parent:
        if _check_includes(child, descendant):
            return child

    return None


def _fold_top_of_stack(stack: list[_Node]):
    child_node = stack.pop()
    if not stack:
        return child_node
    parent_node = stack[-1]
    parent_node.items.append((parent_node.tail_text_segments, child_node))
    parent_node.tail_text_segments = []
    return None


def _check_includes(parent: Element, child: Element) -> bool:
    for _, checked in iter_with_stack(parent):
        if child is checked:
            return True
    return False

from collections.abc import Generator
from dataclasses import dataclass
from typing import cast
from xml.etree.ElementTree import Element

from .common import FoundInvalidIDError, validate_id_in_element
from .inline_segment import InlineError, InlineSegment
from .text_segment import TextSegment
from .utils import IDGenerator, id_in_element


@dataclass
class BlockSubmitter:
    id: int
    origin_text_segments: list[TextSegment]
    submitted_element: Element


@dataclass
class BlockWrongTagError:
    block: tuple[int, Element] | None  # (block_id, block_element) | None 表示根元素
    expected_tag: str
    instead_tag: str


@dataclass
class BlockUnexpectedIDError:
    id: int
    element: Element


@dataclass
class BlockExpectedIDsError:
    id2element: dict[int, Element]


@dataclass
class BlockContentError:
    id: int
    element: Element
    errors: list[InlineError | FoundInvalidIDError]


BlockError = BlockWrongTagError | BlockUnexpectedIDError | BlockExpectedIDsError | BlockContentError


class BlockSegment:
    def __init__(self, root_tag: str, inline_segments: list[InlineSegment]) -> None:
        id_generator = IDGenerator()
        for inline_segment in inline_segments:
            inline_segment.id = id_generator.next_id()
            inline_segment.recreate_ids(id_generator)

        self._root_tag: str = root_tag
        self._inline_segments: list[InlineSegment] = inline_segments
        self._id2inline_segment: dict[int, InlineSegment] = dict((cast(int, s.id), s) for s in self._inline_segments)

    def __iter__(self) -> Generator[InlineSegment, None, None]:
        yield from self._inline_segments

    def create_element(self) -> Element:
        root_element = Element(self._root_tag)
        for inline_segment in self._inline_segments:
            root_element.append(inline_segment.create_element())
        return root_element

    def validate(self, validated_element: Element) -> Generator[BlockError | FoundInvalidIDError, None, None]:
        if validated_element.tag != self._root_tag:
            yield BlockWrongTagError(
                block=None,
                expected_tag=self._root_tag,
                instead_tag=validated_element.tag,
            )

        remain_expected_elements: dict[int, Element] = dict(
            (id, inline_segment.parent) for id, inline_segment in self._id2inline_segment.items()
        )
        for child_validated_element in validated_element:
            element_id = validate_id_in_element(child_validated_element)
            if isinstance(element_id, FoundInvalidIDError):
                yield element_id
            else:
                inline_segment = self._id2inline_segment.get(element_id, None)
                if inline_segment is None:
                    yield BlockUnexpectedIDError(
                        id=element_id,
                        element=child_validated_element,
                    )
                else:
                    if inline_segment.parent.tag != child_validated_element.tag:
                        yield BlockWrongTagError(
                            block=(cast(int, inline_segment.id), inline_segment.parent),
                            expected_tag=inline_segment.parent.tag,
                            instead_tag=child_validated_element.tag,
                        )

                    remain_expected_elements.pop(element_id, None)
                    inline_errors = list(inline_segment.validate(child_validated_element))

                    if inline_errors:
                        yield BlockContentError(
                            id=element_id,
                            element=child_validated_element,
                            errors=inline_errors,
                        )

        if remain_expected_elements:
            yield BlockExpectedIDsError(id2element=remain_expected_elements)

    def submit(self, target: Element) -> Generator[BlockSubmitter, None, None]:
        for child_element in target:
            element_id = id_in_element(child_element)
            if element_id is None:
                continue
            inline_segment = self._id2inline_segment.get(element_id, None)
            if inline_segment is None:
                continue
            inline_segment_id = inline_segment.id
            assert inline_segment_id is not None
            yield BlockSubmitter(
                id=inline_segment_id,
                origin_text_segments=list(inline_segment),
                submitted_element=inline_segment.assign_attributes(child_element),
            )

from collections.abc import Callable, Generator, Iterable, Iterator
from typing import TypeVar
from xml.etree.ElementTree import Element

from resource_segmentation import Group, Resource, Segment, split
from tiktoken import Encoding

from pdf_craft.transformer.xml_translator.segment import InlineSegment, TextSegment, search_inline_segments, search_text_segments
from .callbacks import Callbacks
from .concurrency import run_concurrency
from .score import ScoreSegment, expand_to_score_segments, truncate_score_segment

_PAGE_INCISION = 0
_BLOCK_INCISION = 1
_T = TypeVar("_T")

_ResourcePayload = tuple[InlineSegment, list[ScoreSegment]]


InlineSegmentMapping = tuple[Element, list[TextSegment]]
InlineSegmentGroupMap = Callable[[list[InlineSegment]], list[InlineSegmentMapping | None]]


class XMLStreamMapper:
    def __init__(self, encoding: Encoding, max_group_score: int) -> None:
        self._encoding: Encoding = encoding
        self._max_group_score: int = max_group_score

    def map_stream(
        self,
        elements: Iterator[Element],
        callbacks: Callbacks,
        map: InlineSegmentGroupMap,
        concurrency: int,
    ) -> Generator[tuple[Element, list[InlineSegmentMapping]], None, None]:
        current_element: Element | None = None
        mapping_buffer: list[InlineSegmentMapping] = []

        def execute(group: Group[_ResourcePayload]):
            head, body, tail = self._truncate_and_transform_group(group)
            head = [segment.clone() for segment in head]
            tail = [segment.clone() for segment in tail]
            target_body = map(head + body + tail)[len(head) : len(head) + len(body)]
            return zip(body, target_body, strict=False)

        for mapping_pairs in run_concurrency(
            parameters=self._split_into_serial_groups(elements, callbacks),
            execute=execute,
            concurrency=concurrency,
        ):
            for origin, target in mapping_pairs:
                origin_element = origin.head.root
                if current_element is None:
                    current_element = origin_element

                if id(current_element) != id(origin_element):
                    yield current_element, mapping_buffer
                    current_element = origin_element
                    mapping_buffer = []

                if target:
                    block_element, text_segments = target
                    block_element = callbacks.interrupt_block_element(block_element)
                    text_segments = list(callbacks.interrupt_translated_text_segments(text_segments))
                    if text_segments:
                        mapping_buffer.append((block_element, text_segments))

        if current_element is not None:
            yield current_element, mapping_buffer

    def _split_into_serial_groups(self, elements: Iterable[Element], callbacks: Callbacks):
        def generate():
            for element in elements:
                yield from split(
                    max_segment_count=self._max_group_score,
                    border_incision=_PAGE_INCISION,
                    resources=self._expand_to_resources(element, callbacks),
                )

        generator = generate()
        group = next(generator, None)
        if group is None:
            return

        # head + body * N (without tail)
        sum_count = group.head_remain_count + sum(x.count for x in self._expand_resource_segments(group.body))

        while True:
            next_group = next(generator, None)
            if next_group is None:
                break

            next_sum_body_count = sum(x.count for x in self._expand_resource_segments(next_group.body))
            next_sum_count = sum_count + next_sum_body_count

            if next_sum_count + next_group.tail_remain_count > self._max_group_score:
                yield group
                group = next_group
                sum_count = group.head_remain_count + next_sum_body_count
            else:
                group.body.extend(next_group.body)
                group.tail = next_group.tail
                group.tail_remain_count = next_group.tail_remain_count
                sum_count = next_sum_count

        yield group

    def _truncate_and_transform_group(
        self, group: Group[_ResourcePayload]
    ) -> tuple[list[InlineSegment], list[InlineSegment], list[InlineSegment]]:
        head = self._truncate_group_gap(
            gap=group.head,
            remain_head=False,
            remain_score=group.head_remain_count,
        )
        body = self._expand_inline_segments(group.body)
        tail = self._truncate_group_gap(
            gap=group.tail,
            remain_head=True,
            remain_score=group.tail_remain_count,
        )
        return (
            [r.payload[0] for r in head],
            [p[0] for p in body],
            [r.payload[0] for r in tail],
        )

    def _expand_to_resources(self, element: Element, callbacks: Callbacks):
        def expand(element: Element):
            text_segments = search_text_segments(element)
            text_segments = callbacks.interrupt_source_text_segments(text_segments)
            yield from search_inline_segments(text_segments)

        inline_segment_generator = expand(element)
        start_incision = _PAGE_INCISION
        inline_segment = next(inline_segment_generator, None)
        if inline_segment is None:
            return

        while True:
            next_inline_segment = next(inline_segment_generator, None)
            if next_inline_segment is None:
                break

            if next_inline_segment.head.root is inline_segment.tail.root:
                end_incision = _BLOCK_INCISION
            else:
                end_incision = _PAGE_INCISION

            yield self._transform_to_resource(
                inline_segment=inline_segment,
                start_incision=start_incision,
                end_incision=end_incision,
            )
            inline_segment = next_inline_segment
            start_incision = end_incision

        yield self._transform_to_resource(
            inline_segment=inline_segment,
            start_incision=start_incision,
            end_incision=_PAGE_INCISION,
        )

    def _transform_to_resource(
        self,
        inline_segment: InlineSegment,
        start_incision: int,
        end_incision: int,
    ) -> Resource[_ResourcePayload]:
        source_segments = list(
            expand_to_score_segments(
                encoding=self._encoding,
                inline_segment=inline_segment,
            )
        )
        return Resource(
            count=sum(segment.score for segment in source_segments),
            start_incision=start_incision,
            end_incision=end_incision,
            payload=(inline_segment, source_segments),
        )

    def _expand_inline_segments(self, items: list[Resource[_ResourcePayload] | Segment[_ResourcePayload]]):
        for resource in self._expand_resource_segments(items):
            yield resource.payload

    def _expand_resource_segments(self, items: list[Resource[_ResourcePayload] | Segment[_ResourcePayload]]):
        for item in items:
            if isinstance(item, Resource):
                yield item
            elif isinstance(item, Segment):
                yield from item.resources

    def _truncate_group_gap(
        self,
        gap: list[Resource[_ResourcePayload] | Segment[_ResourcePayload]],
        remain_head: bool,
        remain_score: int,
    ):
        def expand_resource_segments(items: list[Resource[_ResourcePayload] | Segment[_ResourcePayload]]):
            for item in items:
                if isinstance(item, Resource):
                    yield item
                elif isinstance(item, Segment):
                    yield from item.resources

        resources, remain_score = _truncate_items(
            items=expand_resource_segments(gap),
            score=lambda resource: resource.count,
            remain_head=remain_head,
            remain_score=remain_score,
        )
        if remain_score > 0:
            resource = resources.pop() if remain_head else resources.pop(0)
            inline_segment, score_segments = resource.payload
            score_segments, remain_score = _truncate_items(
                items=score_segments,
                score=lambda score_segment: score_segment.score,
                remain_head=remain_head,
                remain_score=remain_score,
            )
            if remain_score > 0:
                score_segment = score_segments.pop() if remain_head else score_segments.pop(0)
                score_segment = truncate_score_segment(
                    score_segment=score_segment,
                    encoding=self._encoding,
                    remain_head=remain_head,
                    remain_score=remain_score,
                )
                if score_segment is not None:
                    if remain_head:
                        score_segments.append(score_segment)
                    else:
                        score_segments.insert(0, score_segment)

                inline_segment = next(
                    search_inline_segments(s.text_segment for s in score_segments),
                    None,
                )

            if inline_segment is not None:
                resource = Resource(
                    count=sum(s.score for s in score_segments),
                    start_incision=resource.start_incision,
                    end_incision=resource.end_incision,
                    payload=(inline_segment, score_segments),
                )
                if remain_head:
                    resources.append(resource)
                else:
                    resources.insert(0, resource)

        return resources


def _truncate_items(items: Iterable[_T], score: Callable[[_T], int], remain_head: bool, remain_score: int):
    truncated_items = list(items)
    if not truncated_items:
        return truncated_items, 0

    if not remain_head:
        truncated_items.reverse()

    truncated_index: int | None = None
    for i, item in enumerate(truncated_items):
        item_score = score(item)
        remain_score -= item_score
        if remain_score <= 0:
            truncated_index = i
            break

    if truncated_index is not None:
        while len(truncated_items) > truncated_index + 1:
            truncated_items.pop()

    if truncated_items and remain_score < 0:
        remain_score = score(truncated_items[-1]) + remain_score
    else:
        remain_score = 0

    if not remain_head:
        truncated_items.reverse()

    return truncated_items, remain_score

